                # Try to find a price near the product name
                match = re.search(re.escape(product_a) + r'.*?' + price_pattern, all_text, re.IGNORECASE | re.DOTALL)
                if match:
                    price_match = re.search(price_pattern, match.group(0))
                    if price_match:
