        title_tag = soup.find('h1')
        if title_tag:
            softwood_info["title"] = title_tag.get_text(strip=True)
        else:
            # Fallback to the page title if no h1 is found
            title_tag = soup.find('title')
            if title_tag:
                softwood_info["title"] = title_tag.get_text(strip=True)

