        ]);
        curl_setopt($ch, CURLOPT_TIMEOUT, 10); // Set a timeout for the request (10 seconds)
        curl_setopt($ch, CURLOPT_CONNECTTIMEOUT, 5); // Set a connection timeout (5 seconds)

        // Execute the cURL request
